// Conservative per-scored-bit MR dependency predicates. All operators below
// are immutable, exact input-only definitions. Fresh MR/opaque symbols stay in
// the outer ANF keys; none may become an input port here.
#[derive(Clone,Copy)]struct MaskNode{kind:u32,a:u32,b:u32,aux:u32}
struct MaskProgram{nodes:Vec<MaskNode>,roots:Vec<u32>,inputs:usize,old_live:usize}
struct MaskBuilder{nodes:Vec<MaskNode>,cache:std::collections::HashMap<(u32,u32,u32),u32>,monos:std::collections::HashMap<u32,u32>}
impl MaskBuilder{
 fn new()->Self{Self{nodes:vec![MaskNode{kind:0,a:0,b:0,aux:0},MaskNode{kind:1,a:0,b:0,aux:0}],cache:std::collections::HashMap::new(),monos:std::collections::HashMap::new()}}
 fn input(&mut self,port:u32)->u32{let id=self.nodes.len()as u32;self.nodes.push(MaskNode{kind:2,a:port,b:0,aux:0});id}
 fn binary(&mut self,kind:u32,mut a:u32,mut b:u32)->u32{assert!((3..=5).contains(&kind));if a>b{std::mem::swap(&mut a,&mut b);}match kind{3=>{if a==0{return b;}if a==b{return 0;}},4=>{if a==0{return 0;}if a==1||a==b{return b;}},5=>{if a==1||b==1{return 1;}if a==0||a==b{return b;}},_=>unreachable!()}let key=(kind,a,b);if let Some(id)=self.cache.get(&key){return *id;}let id=u32::try_from(self.nodes.len()).unwrap();assert!(a<id&&b<id);self.nodes.push(MaskNode{kind,a,b,aux:0});self.cache.insert(key,id);id}
 fn monomial(&mut self,dag:&Dag,id:u32,map:&[u32])->u32{if let Some(out)=self.monos.get(&id){return *out;}let mut out=1;for old in dag.monomials[id as usize].iter(){let factor=map[dag.find(*old)as usize];assert_ne!(factor,u32::MAX);out=self.binary(4,out,factor);}self.monos.insert(id,out);out}
}
impl MaskProgram{
 fn eval(&self,input:&[u64])->Vec<u64>{assert_eq!(input.len(),self.inputs);let mut v=vec![0u64;self.nodes.len()];for(i,n)in self.nodes.iter().enumerate(){assert_eq!(n.aux,0);v[i]=match n.kind{0=>0,1=>u64::MAX,2=>input[n.a as usize],3|4|5=>{assert!((n.a as usize)<i&&(n.b as usize)<i);match n.kind{3=>v[n.a as usize]^v[n.b as usize],4=>v[n.a as usize]&v[n.b as usize],5=>v[n.a as usize]|v[n.b as usize],_=>unreachable!()}},_=>panic!("unsupported mask node")};}self.roots.iter().map(|r|!v[*r as usize]).collect()}
 fn save(&self,path:&str){let mut f=std::io::BufWriter::new(File::create(path).unwrap());f.write_all(b"MRMASK01").unwrap();for count in [self.nodes.len(),self.inputs,self.roots.len()]{f.write_all(&(count as u64).to_le_bytes()).unwrap();}for n in &self.nodes{for x in [n.kind,n.a,n.b,n.aux]{f.write_all(&x.to_le_bytes()).unwrap();}}for r in &self.roots{f.write_all(&r.to_le_bytes()).unwrap();}f.flush().unwrap();}
}
fn compile_mask_program(alg:&GlobalAnf,polys:&[&GlobalPoly],input_ids:&[u32])->MaskProgram{
 let dag=&alg.dag;let mut coefficient_roots=Vec::new();
 for p in polys{let mut r:Vec<u32>=p.0.iter().filter(|(k,_)|!k.is_empty()).map(|(_,c)|dag.find(*c)).filter(|c|*c!=0).collect();r.sort_unstable();r.dedup();if r.contains(&1){r=vec![1];}coefficient_roots.push(r);}
 let ports:std::collections::HashMap<u32,u32>=input_ids.iter().enumerate().map(|(i,id)|(*id,i as u32)).collect();assert_eq!(ports.len(),input_ids.len());
 let mut live=vec![false;dag.nodes.len()];let mut stack:Vec<u32>=coefficient_roots.iter().flatten().copied().collect();
 while let Some(raw)=stack.pop(){let id=dag.find(raw);if live[id as usize]{continue;}live[id as usize]=true;let n=dag.nodes[id as usize];assert!(!n.random,"MR-tainted node in input-only DAG");match n.kind{0|1=>{},2=>{assert!(ports.contains_key(&id),"fresh undeclared opaque/input variable cannot be exported as known input");},3|4=>{stack.push(n.a);stack.push(n.b);},7=>{let t=dag.construction[id as usize];assert!(t.kind==3||t.kind==4);stack.push(t.a);stack.push(t.b);},8=>{stack.extend(dag.monomials[n.a as usize].iter().copied());stack.extend(dag.monomials[n.b as usize].iter().copied());},_=>panic!("missing exact input definition")}}
 let mut map=vec![u32::MAX;dag.nodes.len()];map[0]=0;map[1]=1;let mut c=MaskBuilder::new();
 for i in 2..dag.nodes.len(){if !live[i]{continue;}let id=dag.find(i as u32);if id!=i as u32{map[i]=map[id as usize];continue;}let n=dag.nodes[i];map[i]=match n.kind{2=>c.input(ports[&(i as u32)]),3|4=>{let a=map[dag.find(n.a)as usize];let b=map[dag.find(n.b)as usize];assert_ne!(a,u32::MAX);assert_ne!(b,u32::MAX);c.binary(n.kind as u32,a,b)},7=>{let t=dag.construction[i];assert!(t.kind==3||t.kind==4);let a=map[dag.find(t.a)as usize];let b=map[dag.find(t.b)as usize];assert_ne!(a,u32::MAX);assert_ne!(b,u32::MAX);let out=c.binary(t.kind as u32,a,b);if t.invert{c.binary(3,out,1)}else{out}},8=>{let a=c.monomial(dag,n.a,&map);let b=c.monomial(dag,n.b,&map);c.binary(4,a,b)},_=>unreachable!()};}
 let roots=coefficient_roots.iter().map(|list|{let mut out=0;for r in list{let n=map[*r as usize];assert_ne!(n,u32::MAX);out=c.binary(5,out,n);}out}).collect();
 MaskProgram{nodes:c.nodes,roots,inputs:input_ids.len(),old_live:live.iter().filter(|x|**x).count()}
}
fn export_mask_program(alg:&GlobalAnf,regs:&[Vec<QubitOrBit>],q:&[GlobalPoly],b:&[GlobalPoly],inputs:&[(u32,QubitOrBit)],prefix:&str)->MaskProgram{
 let polys:Vec<_>=regs[..2].iter().flatten().map(|wire|match wire{QubitOrBit::Qubit(id)=>&q[id.0 as usize],QubitOrBit::Bit(id)=>&b[id.0 as usize]}).collect();let program=compile_mask_program(alg,&polys,&inputs.iter().map(|(id,_)|*id).collect::<Vec<_>>());
 program.save(&format!("{prefix}.bin"));
 let ports:Vec<_>=inputs.iter().enumerate().map(|(index,(id,wire))|serde_json::json!({"port":index,"register":index/256,"bit":index%256,"symbolic_input_node":id,"physical_wire":match wire{QubitOrBit::Qubit(id)=>serde_json::json!({"kind":"q","id":id.0}),QubitOrBit::Bit(id)=>serde_json::json!({"kind":"b","id":id.0})}})).collect();
 let outputs:Vec<_>=regs[..2].iter().enumerate().flat_map(|(reg,ws)|ws.iter().enumerate().map(move |(bit,wire)|serde_json::json!({"output":reg*256+bit,"register":reg,"bit":bit,"physical_wire":match wire{QubitOrBit::Qubit(id)=>serde_json::json!({"kind":"q","id":id.0}),QubitOrBit::Bit(id)=>serde_json::json!({"kind":"b","id":id.0})}}))).collect();
 let report=serde_json::json!({"source_commit":"4b2ec52fc55da796aa8f5ef851290297e8706424","original_stream_sha256":"2a522394cdf3e6a0df7784ad4db761030933c1f7ccd0ff8e641d68ec7a4dab3e","magic":"MRMASK01","node_bytes":16,"header_counts":"u64le nodes,inputs,outputs","node_fields":"u32le kind,a,b,aux","kinds":{"0":"CONST0","1":"CONST1","2":"INPUT_PORT(a)","3":"XOR(a,b)","4":"AND(a,b)","5":"OR(a,b)"},"children_strictly_earlier":true,"input_ports":ports,"scored_outputs":outputs,"dependency_roots":program.roots,"input_only_dag_nodes_total":alg.dag.nodes.len(),"input_only_dag_nodes_reachable":program.old_live,"compiled_nodes":program.nodes.len(),"input_count":program.inputs,"output_count":program.roots.len(),"fresh_or_opaque_terminals_exported_as_inputs":0,"input_only_caps_have_exact_immutable_definitions":true,"binary_construction_trace_retained_for_every_cap":true,"independent_expanded_definitions_preserved":true,"mr_and_opaque_rng_symbols_remain_only_outer_polynomial_keys":true,"meaning":"dependency-root upper bound0 guarantees this scored bit independent of every physicalMR and every conservative capped unknown for the supplied publicinput; knownmask=NOTdependencyroot","rejection":"wrong zeroMR scored bit AND knownmask is a sufficient universalMR value-failure witness; unknown bits require original fallback","status":"RESEARCH_INPUT_CONDITIONED_MR_CERTIFICATE_REQUIRES_SOURCE_BINDING_AND_VALIDATION"});std::fs::write(format!("{prefix}.json"),format!("{report}\n")).unwrap();eprintln!("MASK_PROGRAM_EXPORTED nodes={} old_reachable={} original_dag={}",program.nodes.len(),program.old_live,alg.dag.nodes.len());program
}
#[cfg(test)]mod mask_program_tests{use super::*;
 #[test]fn capped_unknown_uses_input_coefficient_not_fresh_input_port(){let mut a=GlobalAnf::new(1);let x=a.dag.variable(false);let m=a.fresh();let n=a.fresh();let mn=a.xor(&m,&n);let p=a.and(&GlobalAnf::constant(x),&mn);assert!(a.capped>0);let c=compile_mask_program(&a,&[&p],&[x]);assert_eq!(c.eval(&[0]),vec![u64::MAX]);assert_eq!(c.eval(&[u64::MAX]),vec![0]);assert_eq!(c.eval(&[0x00ff0ff0f00ff00f]),vec![!0x00ff0ff0f00ff00f]);assert_eq!(c.nodes.iter().filter(|n|n.kind==2).count(),1);}
 #[test]fn always_unknown_root_drops_unreachable_input_dag(){let mut a=GlobalAnf::new(32);let _x=a.dag.variable(false);let p=a.fresh();let c=compile_mask_program(&a,&[&p],&[]);assert_eq!(c.nodes.len(),2);assert_eq!(c.roots,vec![1]);assert_eq!(c.eval(&[]),vec![0]);}
 #[test]fn undeclared_input_or_opaque_terminal_is_rejected(){let mut a=GlobalAnf::new(32);let x=a.dag.variable(false);let p=GlobalPoly(vec![(vec![0],x)]);assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||compile_mask_program(&a,&[&p],&[]))).is_err());}
 #[test]fn retained_large_xor_and_products_compile_exactly(){let mut a=GlobalAnf::new(32);let ids:Vec<_>=(0..80).map(|_|a.dag.variable(false)).collect();let mut sum=0;let mut product=1;for id in &ids{sum=a.dag.xor(sum,*id);product=a.dag.and(product,*id);}assert!(a.dag.nodes.iter().any(|n|n.kind==7));assert!(a.dag.nodes.iter().any(|n|n.kind==8));let p=GlobalPoly(vec![(vec![0],sum),(vec![1],product)]);let c=compile_mask_program(&a,&[&p],&ids);for seed in 0..64u64{let input:Vec<_>=(0..80).map(|j|seed.wrapping_mul(0x9e3779b97f4a7c15).rotate_left(j)^((j as u64).wrapping_mul(0xbf58476d1ce4e5b9))).collect();let dep=input.iter().fold(0,|s,x|s^x)|input.iter().fold(u64::MAX,|s,x|s&x);assert_eq!(c.eval(&input),vec![!dep]);}}
}
